sys_script_include.script:
var CycloidIntegration = Class.create();
CycloidIntegration.prototype = {
    initialize: function() {},

    _getConfig: function() {
        var APP_ID = 'x_1829062_cycloi_1';
        gs.info("Attempting to read configuration from " + APP_ID + "_cycloid_config...");

        var gr = new GlideRecord(APP_ID + '_cycloid_config');
        gs.info("Table exists: " + !gr.isValid());

        var queryResult = gr.query();
        gs.info("Query executed. Number of records found: " + gr.getRowCount());

        if (gr.next()) {
            gs.info("Record found. Retrieving values...");
            var config = {
                api_url: gr.getValue('api_url'),
                org: gr.getValue('organization_canonical'),
                catalog_category: gr.getValue('catalog_category'),
                console_url: gr.getValue('console_url'),
                api_key: gr.getValue('api_key')
            };
            gs.info("Configuration values: " + JSON.stringify(config));
            return config;
        } else {
            gs.error("No records found in " + APP_ID + "_cycloid_config.");
            return null;
        }
    },

    getStacks: function() {
        var config = this._getConfig();
        if (!config) {
            gs.error("Cycloid configuration not found.");
            return [];
        }

        gs.info("Using configuration: " + JSON.stringify(config));

        if (!config.api_url || !config.org || !config.api_key) {
            gs.error("Incomplete configuration: api_url=" + config.api_url + ", org=" + config.org + ", apiKey=" + !!config.api_key);
            return [];
        }

        // Base API URI. The full URL with the query string is constructed.
        // The square brackets '[' and ']' of the 'infra_import_stack[eq]' parameter
        // are replaced by their encoded equivalents (%5B and %5D) to bypass
        // ServiceNow's URI validation.
        var endpoint = config.api_url + '/organizations/' + encodeURIComponent(config.org) + '/service_catalogs?infra_import_stack%5Beq%5D=false&page_index=1&page_size=10000';

        gs.info("Calling Cycloid API at: " + endpoint);

        var rm = new sn_ws.RESTMessageV2();
        rm.setHttpMethod('get');

        // Define the base endpoint.
        rm.setEndpoint(endpoint);

        // The setQueryParameter() methods are no longer necessary
        // as the query string is already built into the URL.
        // rm.setQueryParameter('infra_import_stack[eq]', 'false');
        // rm.setQueryParameter('page_index', '1');
        // rm.setQueryParameter('page_size', '10000');

        rm.setRequestHeader('Accept', 'application/json');
        rm.setRequestHeader('Authorization', 'Bearer ' + config.api_key);

        var response = rm.execute();
        var status = response.getStatusCode();
        var body = response.getBody();

        gs.info("API response status: " + status);

        if (status < 200 || status >= 300) {
            gs.error('Cycloid API Error (' + status + '): ' + body);
            return [];
        }

        try {
            // Added logs to debug the JSON structure
            gs.info("API response body: " + body);
            var json = JSON.parse(body);
            gs.info("Parsed JSON object: " + JSON.stringify(json));
            gs.info("API response parsed successfully.");
            return json.data || json.items || json.stacks || json || [];
        } catch (e) {
            gs.error("JSON parsing error: " + e);
            return [];
        }
    },

    // Method to be called by the scheduled script
    syncStacks: function() {
        gs.info('Starting stack synchronization with Cycloid API.');
        var config = this._getConfig();
        if (!config) {
            gs.error("Cycloid configuration not found. Cannot synchronize stacks.");
            return;
        }

        var stacks = this.getStacks();
        if (stacks.length === 0) {
            gs.info('No stacks were retrieved. Check logs for errors.');
            return;
        }

        gs.info('Successfully retrieved ' + stacks.length + ' stacks.');

        var categoryName = config.catalog_category || 'Cycloid Stacks';
        var categorySysId = this._getOrCreateCategory(categoryName);
        if (!categorySysId) {
            gs.error("Failed to get or create the service catalog category: " + categoryName);
            return;
        }

        gs.info("Using service catalog category: " + categoryName + " (Sys ID: " + categorySysId + ")");

        var APP_ID = 'x_1829062_cycloi_1';
        var TABLE_NAME = APP_ID + '_cycloid_stack';

        // Loop through each stack and create a new service catalog item
        for (var i = 0; i < stacks.length; i++) {
            var stack = stacks[i];

            // Construct the URL for the catalog item
            var stackUrl = config.console_url + '/organizations/' + config.org + '/stacks/' + stack.ref;

            gs.info("Creating or updating catalog item for stack: " + stack.name);

            var grCatItem = new GlideRecord(TABLE_NAME);

            // Check if a catalog item for this stack already exists
            // Using the custom field 'u_cycloid_stack_ref' to ensure uniqueness
            grCatItem.addQuery('u_cycloid_stack_ref', stack.ref);
            grCatItem.query();

            if (grCatItem.next()) {
                gs.info("Catalog item for " + stack.name + " already exists. Updating.");
                grCatItem.name = stack.name;
                grCatItem.description = stack.description || 'Cycloid Service Catalog Stack';
                grCatItem.category = categorySysId;
                grCatItem.url = stackUrl;
                grCatItem.content_type = 'external';
                grCatItem.active = true;
                grCatItem.sys_class_name = TABLE_NAME;
                grCatItem.update();
            } else {
                grCatItem.initialize();
                grCatItem.name = stack.name;
                grCatItem.description = stack.description || 'Cycloid Service Catalog Stack';
                grCatItem.category = categorySysId;
                grCatItem.url = stackUrl;
                grCatItem.content_type = 'external';
                grCatItem.active = true;
                grCatItem.sys_class_name = TABLE_NAME;
                grCatItem.setValue('u_cycloid_stack_ref', stack.ref);

                var newItemSysId = grCatItem.insert();
                if (newItemSysId) {
                    gs.info("Created new catalog item: " + stack.name + " with Sys ID " + newItemSysId);
                } else {
                    gs.error("Failed to create catalog item for stack: " + stack.name);
                }
            }
        }
    },

    _getOrCreateCategory: function(categoryName) {
        var grCat = new GlideRecord('sc_cat_item_category');
        // New check to ensure the table can be accessed before trying to use it
        if (!grCat.isValid()) {
            gs.error("Table 'sc_cat_item_category' is not accessible. Please ensure you have configured a cross-scope privilege for it.");
            return null;
        }

        // The correct field name for the category's display name is 'label'.
        grCat.addQuery('label', categoryName);
        grCat.query();

        if (grCat.next()) {
            gs.info("Found existing service catalog category: " + categoryName);
            return grCat.getUniqueValue();
        } else {
            gs.info("Service catalog category '" + categoryName + "' not found. Creating a new one.");
            var grNewCat = new GlideRecord('sc_cat_item_category');
            grNewCat.initialize();
            // The correct field name for the category's display name is 'label'.
            grNewCat.label = categoryName;

            var newCatSysId = grNewCat.insert();
            if (newCatSysId) {
                gs.info("Created new service catalog category: " + categoryName + " (Sys ID: " + newCatSysId + ")");
                return newCatSysId;
            } else {
                gs.error("Failed to create service catalog category: " + categoryName + ". Check security policies and cross-scope permissions.");
                return null;
            }
        }
    },

    type: 'CycloidIntegration'
};
